-- Puts back the Forever content that 970 (post-Wrath removal) cut by mistake.
-- 2026_11_19_975_world_everlake_post_wrath_restore.sql: written by hand; the rows below are copied from a world built
-- the way CI builds the PTR's, up to 971.
--
-- 970 kept a template only when everlake_import_rows named it, and the core's sql/custom/world files don't write to that
-- table. So it also cut creature and gameobject templates that core files add: EG Link live data, Forever sniffs, the
-- Forever quest restore, Drowned City, player-cache data, the Forever baseline. It also cut a few world-data rows the
-- same way (for example the Tablets of I'lalai 642943-642946 and The Lost Magic of the Runemasters 650929).
-- How the rows were found: run 970 on two copies of a pre-970 world. The first copy ran 970 as merged. The second
-- copy also kept every creature, gameobject and quest template that any core sql/custom/world file or world-data file
-- inserts, plus templates whose row differs from the bare Forever TDB. Quest rows that differ only because a core
-- file blanks QuestPackageID and Portrait* on every quest don't count. Then run 971 on both, and copy here every row
-- the second copy has and the first lacks:
-- 2,029 creature templates and 790 gameobject templates, with their models, difficulties, locales, addons, quest
-- starters and enders, quest items, loot, gossip, trainer, SmartAI and condition rows. No quest was cut that way.
--
-- Safe on any world that ran 970, whichever files it got before it. A row goes in only where it is missing (loot
-- has no primary key, so there a row counts as present only when every column matches). Each template it adds is
-- recorded in everlake_import_rows. Running it again changes nothing. Not checked in game. Never edit this file
-- once it is deployed: a later fix is a new file.


CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

START TRANSACTION;


